import React from 'react';
import { ChevronDown, GraduationCap, Building2, Key, Info, FileText, Newspaper, BookOpen } from 'lucide-react';

const quickLinks = [
    { name: 'FACILITIES', icon: Building2, color: 'bg-white text-coral border border-slate-200 hover:border-coral hover:bg-coral/5', hasDropdown: true },
    { name: 'ADMISSION', icon: GraduationCap, color: 'bg-coral text-white border border-coral hover:bg-coral2', hasDropdown: false },
    { name: 'HOSTEL', icon: Building2, color: 'bg-white text-coral border border-slate-200 hover:border-coral hover:bg-coral/5', hasDropdown: false },
    { name: 'LOGIN', icon: Key, color: 'bg-white text-coral border border-slate-200 hover:border-coral hover:bg-coral/5', hasDropdown: true },
    { name: 'DISCLOSURES', icon: Info, color: 'bg-white text-coral border border-slate-200 hover:border-coral hover:bg-coral/5', hasDropdown: false },
    { name: 'BLOG', icon: FileText, color: 'bg-white text-coral border border-slate-200 hover:border-coral hover:bg-coral/5', hasDropdown: false },
    { name: 'NEWS-EVENTS', icon: Newspaper, color: 'bg-white text-coral border border-slate-200 hover:border-coral hover:bg-coral/5', hasDropdown: false },
    { name: 'CENTRAL LIBRARY', icon: BookOpen, color: 'bg-white text-coral border border-slate-200 hover:border-coral hover:bg-coral/5', hasDropdown: false },
];

const announcements = [
    "New Result - B.Tech S6 (S) Exam, November 2025 (2022 Scheme)",
    "New Result - B.Tech S1 (R) Exam, December 2025 (2023 Scheme)",
    "Registration open for Annual Technical Fest 2025",
    "Notification regarding odd semester fee payment",
    "Guidelines for B.Tech Honors Registration published",
];

const upcomingEvents = [
    "» College of Engineering Chengannur is organizing the National Conference on Emerging Technologies from 19th to 21st December 2025.",
    "» The Department of Computer Science is organizing a Six-day AICTE Training and Learning (ATAL) Online Faculty Development Programme.",
    "» Annual Techfest 'Drishti 2025' dates announced.",
];

const events = [
    "» The 7th International Conference on Modelling and Simulation",
    "» Summer internship program - Computer Science Dept",
    "» Internship on Optical Communication Design with Opticystem",
    "» Workshop on Advanced AI and Machine Learning",
];

// Helper to duplicate items for smooth infinite scrolling
const ScrollList = ({ items }) => (
    <div className="relative h-[300px] w-full overflow-hidden px-4">
        <style>
            {`
            @keyframes scrollVertical {
                0% { transform: translateY(0); }
                100% { transform: translateY(-50%); }
            }
            .anim-scroll {
                animation: scrollVertical 20s linear infinite;
            }
            .anim-scroll:hover {
                animation-play-state: paused;
            }
            `}
        </style>
        <div className="w-full anim-scroll pb-4">
            <ul className="flex flex-col gap-6 pb-6 pt-4 pr-4">
                {items.map((item, idx) => (
                    <li key={`first-${idx}`} className="text-[1.05rem] leading-[1.7] text-slate-700 border-b border-slate-100 pb-5 last:border-0 cursor-pointer hover:text-coral hover:font-semibold transition-all">
                        {item}
                    </li>
                ))}
            </ul>
            <ul className="flex flex-col gap-6 pb-6 pr-4" aria-hidden="true">
                {items.map((item, idx) => (
                    <li key={`second-${idx}`} className="text-[1.05rem] leading-[1.7] text-slate-700 border-b border-slate-100 pb-5 last:border-0 cursor-pointer hover:text-coral hover:font-semibold transition-all">
                        {item}
                    </li>
                ))}
            </ul>
        </div>
    </div>
);

const NoticeUpdates = () => {
    return (
        <section className="relative w-full bg-slate-50 py-12 overflow-hidden">
            {/* Quick Links Row */}
            <div className="w-full px-4 lg:px-10 mb-10">
                <div className="flex flex-wrap justify-center gap-4">
                    {quickLinks.map((link, idx) => (
                        <button key={idx} className={`flex items-center gap-2 px-8 py-[12px] rounded-full font-bold text-[0.95rem] uppercase tracking-[0.05em] transition-all duration-300 shadow-sm ${link.color}`}>
                            <link.icon size={18} className={`opacity-90 ${link.name === 'ADMISSION' ? 'text-white' : 'text-coral'}`} />
                            <span>{link.name}</span>
                            {link.hasDropdown && <ChevronDown size={14} className="ml-1 opacity-70" />}
                        </button>
                    ))}
                </div>
            </div>

            {/* 3 Columns Board */}
            <div className="w-full px-4 lg:px-10">
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 lg:gap-8">
                    {/* Announcement */}
                    <div className="bg-white rounded-[16px] shadow-[0_8px_30px_rgba(10,22,40,0.04)] border border-slate-100 overflow-hidden hover:shadow-[0_8px_30px_rgba(10,22,40,0.08)] transition-shadow duration-300">
                        <div className="bg-gradient-to-r from-coral to-coral2 py-5 px-6 text-center border-b-[3px] border-gold">
                            <h3 className="font-display text-[1.3rem] font-extrabold text-white uppercase tracking-[0.1em]">Announcements</h3>
                        </div>
                        <ScrollList items={announcements} />
                    </div>

                    {/* Upcoming Events */}
                    <div className="bg-white rounded-[16px] shadow-[0_8px_30px_rgba(10,22,40,0.04)] border border-slate-100 overflow-hidden hover:shadow-[0_8px_30px_rgba(10,22,40,0.08)] transition-shadow duration-300">
                        <div className="bg-gradient-to-r from-coral to-coral2 py-5 px-6 text-center border-b-[3px] border-gold">
                            <h3 className="font-display text-[1.3rem] font-extrabold text-white uppercase tracking-[0.1em]">Notifications</h3>
                        </div>
                        <ScrollList items={upcomingEvents} />
                    </div>

                    {/* Events */}
                    <div className="bg-white rounded-[16px] shadow-[0_8px_30px_rgba(10,22,40,0.04)] border border-slate-100 overflow-hidden hover:shadow-[0_8px_30px_rgba(10,22,40,0.08)] transition-shadow duration-300">
                        <div className="bg-gradient-to-r from-coral to-coral2 py-5 px-6 text-center border-b-[3px] border-gold">
                            <h3 className="font-display text-[1.3rem] font-extrabold text-white uppercase tracking-[0.1em]">Notice Board</h3>
                        </div>
                        <ScrollList items={events} />
                    </div>
                </div>
            </div>
        </section>
    );
};

export default NoticeUpdates;
